/* Offline retrieval baseline. This is lexical vector search, not a semantic model. */
(function(root){
const stop=new Set('the a an and or of in on to for is are was were with that this it be as by from at we you i our your can will have has do not'.split(' '));
const tokens=s=>(s.toLowerCase().match(/[\p{L}\p{N}]+/gu)||[]).filter(x=>x.length>2&&!stop.has(x));
function vector(s){const v={};for(const t of tokens(s))v[t]=(v[t]||0)+1;return v}
function cosine(a,b){let dot=0,aa=0,bb=0;for(const k in a){aa+=a[k]*a[k];dot+=a[k]*(b[k]||0)}for(const k in b)bb+=b[k]*b[k];return aa&&bb?dot/Math.sqrt(aa*bb):0}
function chunk(s,size=1100,overlap=150){const out=[];let start=0;while(start<s.length){let end=Math.min(start+size,s.length);if(end<s.length){let cut=s.lastIndexOf('\n',end);if(cut>start+size/2)end=cut}out.push(s.slice(start,end));if(end===s.length)break;start=Math.max(start+1,end-overlap)}return out}
function retrieve(query,notes,limit=3){const q=vector(query);return notes.flatMap(n=>chunk(n.text).map((text,i)=>({sourceId:n.id,title:n.title,date:n.date,dateVerified:n.dateVerified,chunk:i,text,score:cosine(q,vector(text))}))).filter(x=>x.score>=.18).sort((a,b)=>b.score-a.score).slice(0,limit)}
function topics(segments){const text=segments.map(s=>s.text).join(' ');const groups=[['AI agents',/\bagents?\b|agentic|orchestrat|langgraph|adk/i],['Cloud infrastructure',/cloud|kubernetes|gcp|aws|vertex|infrastructure/i],['Memory & retrieval',/memory|retriev|embedding|vector|rag\b/i],['Evaluation & reliability',/evaluat|test|reliab|benchmark|accuracy|hallucin/i],['Privacy & security',/privacy|security|consent|encrypt|permission/i],['Tools & announcements',/announc|launch|release|tool|framework/i]];let out=groups.map(([title,re])=>({title,segments:segments.filter(s=>re.test(s.text))})).filter(x=>x.segments.length);if(!out.length&&text)out=[{title:'Session highlights',segments:segments.slice(-6)}];return out.map(x=>({...x,text:x.segments.map(s=>s.text).join(' ')}))}
function extractJSON(input){let data;try{data=JSON.parse(input)}catch{return input}if(Array.isArray(data)&&data.some(x=>x.mapping)){return data.map(c=>`# ${c.title||'Conversation'}\n`+Object.values(c.mapping||{}).map(n=>{const m=n.message;return m&&Array.isArray(m.content?.parts)?`${m.author?.role||'speaker'}: ${m.content.parts.filter(p=>typeof p==='string').join('\n')}`:''}).filter(Boolean).join('\n')).join('\n\n')}if(Array.isArray(data)&&data.some(x=>x.role))return data.map(x=>`${x.role}: ${typeof x.content==='string'?x.content:JSON.stringify(x.content)}`).join('\n');return JSON.stringify(data,null,2)}
const api={tokens,vector,cosine,chunk,retrieve,topics,extractJSON};root.EMEngine=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
